    n = int(stdin.readline())
    a = list(map(int, stdin.readline().split()))
    parent = [i for i in range(n+1)]  # 1-based

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        parent[v_root] = u_root
        return True

    root = -1
    cycles = 0
    for i in range(1, n+1):
