import sys
from bisect import bisect_right

sys.setrecursionlimit(1 << 25)

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    edges = [[] for _ in range(n+1)]
    for i in range(2, n+1):
        p, w = map(int, sys.stdin.readline().split())
        edges[i].append((p, w))
        edges[p].append((i, w))

    parent = [0]*(n+1)
    edge_weights = [0]*(n+1)
    for i in range(2, n+1):
        for p, w in edges[i]:
            if p < i:
                parent[i] = p
                edge_weights[i] = w
                break

    answer = [0]*(n+1)
    path = []
    dists = [0]*(n+1)

    stack = [(1, False)]
    while stack:
        v, visited = stack.pop()
        if visited:
            idx = bisect_right(path, (dists[v] - a[v-1], 0)) - 1
            if idx >= 0:
                answer[path[idx][1]] -= 1
            if path:
                answer[path[-1][1]] += 1
            path.pop()
            continue

        path.append((dists[v], v))
        stack.append((v, True))

        for u in edges[v]:
            if u[0] == parent[v]:
                continue
            if u[0] == parent[u[0]]:
                dists[u[0]] = dists[v] + u[1]
            stack.append((u[0], False))

    result = [0]*(n+1)

    stack = [(1, False)]
    while stack:
        v, visited = stack.pop()
        if visited:
            for child in edges[v]:
                u = child[0]
                if u != parent[v]:
                    result[v] += result[u]
            result[v] += answer[v]
            continue

        stack.append((v, True))
        for child in edges[v]:
            u = child[0]
            if u != parent[v]:
                stack.append((u, False))

    print(' '.join(map(str, result[1:n+1])))

if __name__ == "__main__":
    main()

