def process_text(text):
    # Split into tokens (words and punctuation)
    tokens = re.findall(r'[a-z]+|[.,!?]', text)
    result = []
    prev = None
    for token in tokens:
        if token in {'.', ',', '!', '?'}:
            # Punctuation: remove any space before, add one after
            if result and result[-1] == ' ':
                result.pop()
            result.append(token)
            result.append(' ')
            prev = 'punct'
        else:
            # Word: add space if previous was word or punct (but space added)
            if prev in {'word', 'punct'}:
                result.append(' ')
            result.append(token)
            prev = 'word'
    # Remove trailing space if any
    if result and result[-1] == ' ':
        result.pop()
    return ''.join(result)

