def find_reversal_segment(perm, n):
    # Find the first index where the permutation deviates from 1..n
    start = 0
    while start < n and perm[start] == start + 1:
        start += 1

    # If all elements are in place, no reversal (needs exactly one, so return 0 0)
    if start == n:
        return (0, 0)

    # Find the end index where the permutation resumes the correct sequence
    end = n - 1
    while end >= 0 and perm[end] == end + 1:
        end -= 1

    # Reverse the segment from start to end and check if it matches the original sequence
    reversed_segment = perm[start:end+1][::-1]
    original_segment = list(range(start+1, end+2))  # Correct sequence should be start+1 to end+1

    if reversed_segment != original_segment:
        return (0, 0)

    # Check if the elements before start and after end are correctly placed
    for i in range(start):
        if perm[i] != i + 1:
            return (0, 0)
    for i in range(end + 1, n):
        if perm[i] != i + 1:
            return (0, 0)

    return (start + 1, end + 1)  # Converting 0-based to 1-based

