import math
from fractions import Fraction

def solve():
    n = int(input().strip())
    if n == 1:
        print("0/1")
        return

    m = n.bit_length()
    if (1 << m) > n:
        m -= 1
    k = 1 << m
    if k == n:
        total = Fraction(m * n, 1)
    else:
        total = Fraction(m * k, 1) + Fraction(n - k, 1) * (m + 1)
        total += Fraction((1 << (m + 1)) - n, 1) * solve_rec(n, m + 1)
        total /= Fraction(n, 1)

    print(f"{total.numerator}/{total.denominator}")

def solve_rec(n, depth):
    if n == 0:
        return Fraction(0, 1)
    m = depth
    k = 1 << m
    if k >= n:
        return Fraction(m, 1)
    else:
        return Fraction(m * k + (n - k) * (m + 1), n) + Fraction(( (1 << (m + 1)) - n ) * solve_rec(n - k, m + 1), n)

